#include "libs/st7789/spi_interface/spi_interface.h"

typedef struct {
    uint16_t height, width;
} sprite_dimensions_t;

typedef struct {
    uint16_t left, top, right, bottom;
} sprite_position_t;

typedef struct {
    uint16_t *img;
    uint16_t array_length;
    sprite_dimensions_t dimensions;
    sprite_position_t position;
} sprite_t;

// Motion directions
typedef enum {
    N_, // UP
    NE, // UP-RIGHT
    E_, // RIGHT
    SE, // DOWN-RIGHT
    S_, // DOWN
    SW, // DOWN-LEFT
    W_, // LEFT
    NW, // UP-LEFT
} sprite_motion_dir_t;

